package org.securemail.ui;

import com.google.gson.*;
import javafx.scene.Node;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import java.time.*;
import java.util.*;
import static org.securemail.ui.CommunityUi.*;

/** Paginated news, moderation and event registration use the same server ACL as the library. */
final class NewsView {
  private final CommunityUi api;private final BorderPane root=new BorderPane();private final ScrollPane page=scroll(root);private final VBox detail=new VBox(10);private final ScrollPane detailScroll=scroll(detail);private final VBox eventContent=new VBox(10);private final Label status=label("");private final ListView<JsonObject> news=list("Доступных публикаций пока нет");private final String organization;private String feed,cursor="";private final TextField query=field("Поиск публикаций");private final CityPicker city;private final VBox left=new VBox(8);private final SplitPane split=new SplitPane();private final EventsCalendar calendar;private JsonObject current;
  NewsView(CommunityUi api){this(api,"GLOBAL","");}
  NewsView(CommunityUi api,String initial,String organization){this.api=api;this.city=new CityPicker(api,"");this.feed=initial;this.organization=organization;calendar=new EventsCalendar(this::open,m->{if(feed.equals("EVENTS"))refresh(false);});root.setId("news-page");root.setMinHeight(Region.USE_PREF_SIZE);split.setMinHeight(340);split.setPrefHeight(500);ComboBox<String> categories=new ComboBox<>();categories.getItems().setAll("Всеобщие","Мой город","Мои организации","Мероприятия");categories.getSelectionModel().select(initial.equals("CITY")?1:initial.equals("ORGANIZATIONS")?2:initial.equals("EVENTS")?3:0);categories.setOnAction(e->{feed=switch(categories.getSelectionModel().getSelectedIndex()){case 1->"CITY";case 2->"ORGANIZATIONS";case 3->"EVENTS";default->"GLOBAL";};layoutFeed();refresh(false);});root.setTop(card(heading("Новости"),actions(categories,query,button("Найти",()->refresh(false)),button("Новая публикация",()->edit(null)),button("Мероприятие",this::newEvent)),fold("География",card(label("Город выбирается вручную. Геолокация по IP не используется."),city.node())),status));news.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b!=null)open(b);});root.setCenter(split);root.widthProperty().addListener((o,a,b)->orient());layoutFeed();refresh(false);}
  Node node(){return page;}
  private void orient(){split.setOrientation(feed.equals("EVENTS")||root.getWidth()<700?javafx.geometry.Orientation.VERTICAL:javafx.geometry.Orientation.HORIZONTAL);}
  private void layoutFeed(){if(feed.equals("EVENTS")){split.getItems().clear();left.getChildren().clear();detailScroll.setContent(null);eventContent.getChildren().setAll(calendar,button("Загрузить ещё",()->refresh(true)),detail);root.setCenter(eventContent);}else{eventContent.getChildren().clear();detailScroll.setContent(detail);left.getChildren().setAll(news,button("Загрузить ещё",()->refresh(true)));VBox.setVgrow(news,Priority.ALWAYS);split.getItems().setAll(left,detailScroll);root.setCenter(split);orient();split.setDividerPositions(.35);}}
  private String base(){return feed.equals("EVENTS")?"content.events":"content.news";}
  private void refresh(boolean more){if(feed.equals("CITY")&&city.id().isEmpty()){status.setText("Выберите город в разделе «География».");return;}if(more&&(cursor.isEmpty()||news.getItems().size()>=500)){status.setText(cursor.isEmpty()?"Все полученные страницы показаны.":"Показано 500 записей. Уточните поиск.");return;}if(!more){cursor="";news.getItems().clear();calendar.data(List.of());}String requestedFeed=feed;YearMonth requestedMonth=calendar.month();JsonObject request=obj("feed",feed.equals("EVENTS")?"ALL":feed,"cityId",city.id(),"organization",organization,"query",query.getText(),"cursor",cursor,"limit",40);if(feed.equals("EVENTS")){ZoneId zone=ZoneId.systemDefault();request.addProperty("startsFrom",requestedMonth.atDay(1).atStartOfDay(zone).toInstant().toEpochMilli());request.addProperty("startsTo",requestedMonth.plusMonths(1).atDay(1).atStartOfDay(zone).toInstant().toEpochMilli()-1);}api.call(base()+".list",request,status,r->{if(!feed.equals(requestedFeed)||(feed.equals("EVENTS")&&!calendar.month().equals(requestedMonth)))return;if(!more)news.getItems().clear();List<JsonObject> rows=items(r,"items");news.getItems().addAll(rows.subList(0,Math.min(rows.size(),500-news.getItems().size())));cursor=str(r,"nextCursor");if(feed.equals("EVENTS"))calendar.data(news.getItems());});}
  private void open(JsonObject row){String prefix=str(row,"kind").equalsIgnoreCase("EVENT")?"content.events":"content.news";api.call(prefix+".get",obj("id",str(row,"id")),status,value->{current=value;detail.getChildren().setAll(heading(title(value)),label(str(value,"ai").equals("true")?"Подготовлено ИИ":""),label("Состояние: "+state(str(value,"state"))),DocumentEditor.render(str(value,"body"),api.openLink));for(JsonElement source:array(value,"sources")){String url=source.isJsonPrimitive()?source.getAsString():source.toString();if(DocumentEditor.safe(url)){Hyperlink link=new Hyperlink(url);link.setOnAction(e->api.openLink.accept(url));detail.getChildren().add(link);}}detail.getChildren().add(fold("Редакционные действия",actions(button("Изменить",()->edit(value)),button("Отправить на проверку",()->revision(prefix+".submit",value,obj())),button("Одобрить",()->revision(prefix+".moderate",value,obj("decision","APPROVE"))),button("Отклонить",()->revision(prefix+".moderate",value,obj("decision","REJECT"))),button("Опубликовать",()->revision(prefix+".publish",value,obj())),button("Отозвать публикацию",()->revision(prefix+".retract",value,obj())))));detail.getChildren().add(MaterialFiles.node(api,value,status,()->open(value)));if(prefix.endsWith("events")){detail.getChildren().addAll(label("Начало: "+date(number(value,"startsAt"))),label(str(value,"location")),button("Зарегистрироваться",()->api.call("content.events.register",obj("id",str(value,"id")),status,r->status.setText("Регистрация подтверждена сервером."))),button("Отменить мероприятие",()->revision("content.events.cancel",value,obj())));}else detail.getChildren().addAll(actions(button("Нравится",()->api.call("content.news.react",obj("id",str(value,"id"),"reaction","Нравится"),status,r->open(value))),button("История исправлений",()->revisions(value,prefix))),poll(value));});}
  private Node poll(JsonObject value){TextField question=field("Вопрос опроса"),options=field("Варианты ответа через запятую");VBox body=card(question,options,button("Создать опрос",()->api.call("content.news.poll.create",obj("id",str(value,"id"),"question",question.getText(),"options",strings(options.getText())),status,r->open(value))));if(value.has("pollQuestion")){body.getChildren().add(label(str(value,"pollQuestion")));for(JsonObject option:items(value,"pollOptions"))body.getChildren().add(button(str(option,"label")+" · "+number(option,"votes"),()->api.call("content.news.poll.vote",obj("id",str(value,"id"),"optionId",str(option,"id")),status,r->open(value))));}return fold("Опрос",body);}
  private void revision(String action,JsonObject value,JsonObject args){args.addProperty("id",str(value,"id"));args.addProperty("revision",number(value,"revision"));api.call(action,args,status,r->{status.setText("Изменение подтверждено сервером.");refresh(false);});}
  private void edit(JsonObject value){if(value!=null&&str(value,"kind").equals("EVENT")){eventEditor(value);return;}TextField title=field("Заголовок"),organizationField=field("Организация (необязательно)");title.setText(value==null?"":str(value,"title"));organizationField.setText(value==null?organization:str(value,"organization"));ComboBox<String> distribution=distribution(value==null?(organization.isEmpty()?feed.equals("CITY")?"CITY":"GLOBAL":"ORGANIZATION"):str(value,"distribution"));TextArea sources=new TextArea();sources.setPromptText("Источники: одна HTTPS-ссылка в строке");sources.setPrefRowCount(2);sources.setWrapText(true);if(value!=null)sources.setText(String.join("\n",itemsAsStrings(array(value,"sources"))));DocumentEditor document=new DocumentEditor(api.openLink);document.text(value==null?"":str(value,"body"));MaterialPolicyEditor policy=new MaterialPolicyEditor(value,organization);VBox form=card(heading(value==null?"Новая публикация":"Редактирование публикации"),title,organizationField,distribution,sources,document.node(),policy.node(),button("Сохранить черновик",()->{JsonObject args=obj("title",title.getText(),"body",document.text(),"organization",organizationField.getText(),"cityId",organizationField.getText().isBlank()?city.id():"","sources",sourceLines(sources.getText()),"distribution",distribution.getValue(),"policy",policy.value(organizationField.getText()));if(value!=null){args.remove("organization");args.remove("cityId");args.remove("distribution");args.addProperty("id",str(value,"id"));args.addProperty("revision",number(value,"revision"));}api.call("content.news."+(value==null?"create":"update"),args,status,r->{open(r);refresh(false);});}));detail.getChildren().setAll(form);}
  private void newEvent(){eventEditor(null);}
  private void eventEditor(JsonObject value){TextField title=field("Название мероприятия"),date=field("Дата и время, например 2026-11-01T18:00"),location=field("Место или ссылка"),capacity=field("Количество мест");title.setText(value==null?"":str(value,"title"));location.setText(value==null?"":str(value,"location"));capacity.setText(value==null?"100":str(value,"capacity"));if(value!=null&&number(value,"startsAt")>0)date.setText(Instant.ofEpochMilli(number(value,"startsAt")).atZone(ZoneId.systemDefault()).toLocalDateTime().toString());ComboBox<String> distribution=distribution(value==null?(organization.isEmpty()?city.id().isBlank()?"GLOBAL":"CITY":"ORGANIZATION"):str(value,"distribution"));CheckBox online=new CheckBox("Онлайн-формат");online.setSelected(value!=null&&str(value,"online").equals("true"));DocumentEditor document=new DocumentEditor(api.openLink);document.text(value==null?"":str(value,"body"));MaterialPolicyEditor policy=new MaterialPolicyEditor(value,value==null?organization:str(value,"organization"));detail.getChildren().setAll(card(heading(value==null?"Новое мероприятие":"Изменение мероприятия"),title,date,location,capacity,online,distribution,document.node(),policy.node(),button("Сохранить мероприятие",()->{try{long starts=LocalDateTime.parse(date.getText().trim()).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();int seats=Integer.parseInt(capacity.getText());JsonObject args=obj("title",title.getText(),"body",document.text(),"startsAt",starts,"location",location.getText(),"online",online.isSelected(),"capacity",seats,"policy",policy.value());if(value==null){args.addProperty("organization",organization);args.addProperty("cityId",organization.isBlank()?city.id():"");args.addProperty("distribution",distribution.getValue());}else{args.addProperty("id",str(value,"id"));args.addProperty("revision",number(value,"revision"));}api.call("content.events."+(value==null?"create":"update"),args,status,r->{open(r);refresh(false);});}catch(Exception invalid){status.setText("Проверьте дату, время и количество мест.");}})));}
  private static ComboBox<String> distribution(String initial){ComboBox<String> box=new ComboBox<>();box.getItems().setAll("GLOBAL","CITY","ORGANIZATION");box.setConverter(new javafx.util.StringConverter<>(){public String toString(String value){return switch(value==null?"":value){case "CITY"->"Городская лента";case "ORGANIZATION"->"Лента организации";default->"Всеобщая лента";};}public String fromString(String value){return value;}});box.setValue(initial);box.setAccessibleText("Лента публикации");box.setTooltip(new Tooltip("Охват ленты и права чтения проверяются отдельно. Всеобщая публикация требует глобального полномочия."));return box;}
  private static List<String> itemsAsStrings(JsonArray values){List<String> result=new ArrayList<>();for(JsonElement value:values)if(value.isJsonPrimitive())result.add(value.getAsString());return result;}
  private static JsonArray sourceLines(String lines){JsonArray result=new JsonArray();lines.lines().map(String::strip).filter(s->!s.isEmpty()).forEach(result::add);return result;}
  private void revisions(JsonObject value,String prefix){revisionPage(value,prefix,0);}
  private void revisionPage(JsonObject value,String prefix,long cursor){JsonObject args=obj("id",str(value,"id"),"limit",5);if(cursor>0)args.addProperty("cursor",cursor);api.call(prefix+".revisions",args,status,r->{VBox body=new VBox(8,heading("История исправлений"),button("К публикации",()->open(value)));for(JsonObject revision:items(r,"items"))body.getChildren().add(card(label("Версия "+str(revision,"revision")+" · "+str(revision,"editor")),DocumentEditor.render(str(revision,"body"),api.openLink),button("Восстановить эту версию",()->revision(prefix+".revert",value,obj("targetRevision",number(revision,"revision"))))));long next=number(r,"nextCursor");if(next>0)body.getChildren().add(button("Более ранние версии",()->revisionPage(value,prefix,next)));if(cursor>0)body.getChildren().add(button("Последние версии",()->revisionPage(value,prefix,0)));detail.getChildren().setAll(body);});}
  static String state(String value){return switch(value){case "DRAFT"->"Черновик";case "PENDING","REVIEW","SUBMITTED","AWAITING_REVIEW"->"Ожидает проверки";case "APPROVED"->"Одобрено";case "PUBLISHED"->"Опубликовано";case "CORRECTED"->"Исправлено";case "WITHDRAWN","RETRACTED"->"Отозвано";case "REJECTED"->"Отклонено";default->"Не опубликовано";};}
  static String date(long value){return value<=0?"Не указано":java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm").withZone(ZoneId.systemDefault()).format(Instant.ofEpochMilli(value));}
}
